var distributions = $input.first().json.data || [];
var results = [];

for (var i = 0; i < distributions.length; i++) {
  var dist = distributions[i];
  var deal = dist.deal || {};
  var buyer = dist.buyer || {};

  var skipStatuses = ['sold', 'expired', 'dead', 'under_contract'];
  var shouldSkip = deal.status && skipStatuses.indexOf(deal.status) !== -1;

  if (!shouldSkip) {
    results.push({ json: { distribution: dist, deal: deal, buyer: buyer } });
  }
}

return results;

var distribution = $input.first().json.distribution;
var deal = $input.first().json.deal;
var buyer = $input.first().json.buyer;

var timezone = (buyer.preferences && buyer.preferences.timezone) || 'America/New_York';

var now = new Date();
var currentHour = now.getUTCHours();

var tzOffsets = {
  'America/New_York': -4,
  'America/Chicago': -5,
  'America/Denver': -6,
  'America/Los_Angeles': -7
};
var offset = tzOffsets[timezone] || -4;
var localHour = (currentHour + offset + 24) % 24;

var isBusinessHours = localHour >= 9 && localHour < 20;

return { json: { distribution: distribution, deal: deal, buyer: buyer, isBusinessHours: isBusinessHours } };

var dist = $json;
var status = dist.status;
var followUpCount = dist.follow_up_count || 0;
var buyerName = dist.buyer ? dist.buyer.display_name.split(' ')[0] : 'Investor';
var dealAddress = dist.deal ? dist.deal.property_address : 'the property';
var askingPrice = dist.deal ? dist.deal.asking_price : 0;

var template = '';
var isLastFollowUp = followUpCount >= 3;

if (status === 'ping_sent') {
  if (followUpCount === 0) {
    template = buyerName + ', still interested in ' + dealAddress + '? Reply YES for full details. -Team';
  } else if (followUpCount === 1) {
    template = buyerName + ' - 2 other buyers looking at ' + dealAddress + '. Want details before they lock it? Reply YES. -Team';
  } else if (followUpCount === 2) {
    template = 'Hey ' + buyerName + ', getting offers on ' + dealAddress + '. Need your answer today. YES or PASS? -Team';
  } else {
    template = 'FINAL NOTICE ' + buyerName + ': ' + dealAddress + ' - passing to next buyer in 2 hours. Last chance to reply YES. -Team';
  }
} else if (status === 'details_sent') {
  if (followUpCount === 0) {
    template = buyerName + ', thoughts on ' + dealAddress + '? Reply LOCK to hold it for 24hrs. -Team';
  } else if (followUpCount === 1) {
    template = buyerName + ' - another buyer is reviewing ' + dealAddress + '. Lock it now or lose it? Reply LOCK. -Team';
  } else if (followUpCount === 2) {
    template = 'Hey ' + buyerName + ', need a decision on ' + dealAddress + ' today. LOCK or PASS? -Team';
  } else {
    template = 'FINAL: ' + dealAddress + ' goes to next buyer in 2 hours. Reply LOCK now or it\'s gone. -Team';
  }
} else if (status === 'locked') {
  if (followUpCount === 0) {
    template = buyerName + ', you locked ' + dealAddress + '. Need your email to send the package! -Team';
  } else if (followUpCount === 1) {
    template = buyerName + ' - still need your email for the ' + dealAddress + ' package. Reply with your email address. -Team';
  } else if (followUpCount === 2) {
    template = 'Hey ' + buyerName + ', your hold on ' + dealAddress + ' expires soon. Send your email to get the deal package! -Team';
  } else {
    template = 'URGENT ' + buyerName + ': Hold expiring on ' + dealAddress + '. Reply with EMAIL now or we release it. -Team';
  }
}

var nextFollowUp = isLastFollowUp ? null : Date.now() + (4 * 60 * 60 * 1000);

return {
  json: {
    ...dist,
    smsText: template,
    nextFollowUp: nextFollowUp,
    isLastFollowUp: isLastFollowUp,
    followUpNumber: followUpCount + 1
  }
};

// Check if lead has protected status
var closeData = $json;
var templateData = $('Select Follow-Up Template').first().json;
var statusLabel = (closeData.status_label || '').toLowerCase().trim();

// PROTECTED STATUSES - NO SMS for these
var protectedStatuses = [
  'human hand', 'hot lead', 'hot', 'warm lead',
  'interested', 'not interested', 'dnc', 'dead',
  'vetted buyer', 'vip'
];

var isProtected = protectedStatuses.indexOf(statusLabel) !== -1;

return [{
  json: {
    ...templateData,
    _closeStatus: statusLabel,
    _isProtectedStatus: isProtected,
    canSend: !isProtected
  }
}];

const data=$input.first().json;
const base=$env.INSULA_CRM_BASE_URL;
try {
  const buyerLookup=await this.helpers.httpRequest({
    method:'GET',url:base+'/api/v1/buyers',
    qs:{external_id:data.buyer && (data.buyer._id || data.buyer.id),external_source:'convex_buyer_onboarding',per_page:1},
    headers:{'X-API-Key':$env.INSULA_CRM_API_KEY}
  });
  const dealLookup=await this.helpers.httpRequest({
    method:'GET',url:base+'/api/v1/deals',
    qs:{external_id:data.deal && (data.deal._id || data.deal.id),external_source:'convex_disposition_intake',per_page:1},
    headers:{'X-API-Key':$env.INSULA_CRM_API_KEY}
  });
  const buyer=buyerLookup?.data?.[0], deal=dealLookup?.data?.[0];
  if(buyer && deal){
    await this.helpers.httpRequest({
      method:'POST',
      url:base+'/api/v1/deals/'+deal.id+'/matches',
      headers:{
        'X-API-Key':$env.INSULA_CRM_API_KEY,
        'Content-Type':'application/json',
        'Idempotency-Key':'disposition:followup:'+data.distribution._id+':'+(data.followUpNumber||1)+':v1'
      },
      body:{
        buyer_id:buyer.id,
        status:data.isLastFollowUp?'no_response':'matched',
        outreach_status:'follow_up_sent',
        last_contacted_at:new Date().toISOString(),
        buyer_notes:'Automated follow-up #' + (data.followUpNumber||1)
      },
      json:true
    });
  }
} catch(error) {
  console.log('InsulaCRM follow-up sync failed:',error.message);
}
return [{json:data}];
